  "base-uri 'none'", "form-action 'none'", "frame-ancestors 'none'", "object-src 'none'",
  `script-src 'self' ${shellScripts.join(" ")}`, "style-src 'self' 'unsafe-inline'", "img-src 'self' data:", "media-src 'self'", "font-src 'self'", "connect-src 'self'",
