  if (m[4] === "/presence") return response(req.method === "HEAD" ? null : JSON.stringify({ presences: presences(key, id) }), 200, { "Content-Type": "application/json" });
  if (m[4] === "/versions") return response(req.method === "HEAD" ? null : JSON.stringify({
